import {accountRoles,canEdit,canManageAccounts,allowedAdminTab} from './access.js';
import {reportFields,reportVersion} from './report-edit.js';
import {statisticsPdf} from './statistics-pdf.js';
import {monthlyStatistics,readingStatus,spreadsheetStatistics,spreadsheetCsvRows} from './statistics.js';
import {vehicleIdentity,vehicleStatus,vehicleStatusLabels,vehicleUnit,vehicleUnitNames} from './fleet.js';
import {stockholmDate} from './meter.js';
import {vehicles as stockVehicles} from './data.js';
import {modelImages} from './vehicle-images.js';
import {equipmentFor} from './equipment.js';
import {sectionsFor,sectionNames} from './forms.js';
import {cardLines,cardHtml,isDeviation} from './card-report.js';
import {groupsFor,menuOptions} from './groups.js';
import {textFields,defaults} from './content.js';
const app=document.querySelector('#admin'),esc=v=>String(v??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
window.addEventListener('message',event=>{const frame=app.querySelector('#preview-frame');if(event.origin!==location.origin||!frame||event.source!==frame.contentWindow||event.data?.type!=='QFSV_PREVIEW_READY')return;frame.dataset.ready='1';frame.dispatchEvent(new Event('qfsv:preview-ready'))});
let meterAdmin={today:stockholmDate(),rows:[]},scheduleDraft=null;
let cards=[],config,me,tab=location.hash.slice(1)||'overview',filters={from:'',to:'',vehicle:'',driver:'',status:''};
function navigateTab(id){if(id!==tab){const url=new URL(location.href);url.hash=id;history.pushState(null,'',url)}tab=id;render()}
function restoreTab(){if(!me||!config)return;const id=location.hash.slice(1)||'overview';if(id!==tab){tab=id;render()}}
window.addEventListener('popstate',restoreTab);window.addEventListener('hashchange',restoreTab);
async function api(path,method='GET',body){const r=await fetch('./api/'+path,{method,headers:{'Content-Type':'application/json'},...(body?{body:JSON.stringify(body)}:{})});let data;try{data=await r.json()}catch{throw new Error('Admin kräver appens server och databas. Den fungerar inte på GitHub Pages.')}if(!r.ok)throw new Error(data.error||'Begäran misslyckades.');return data}
const name=c=>c.snapshot?.name||(c.name==='Övrigt'?c.otherName:c.name);
const vehicle=c=>c.snapshot?.vehicle?.[1]||config.vehicles.find(v=>v[0]===c.vehicle)?.[1]||c.vehicle;
const faults=c=>Object.entries(c).filter(([k,v])=>!k.endsWith('_comment')&&(/^(daily|week|extra|light)\d+$/.test(k)||k.startsWith('q_')||k.startsWith('e_'))&&['Skall repareras','Skall bytas','Fel'].includes(v)).length+(c.carStatus==='Fel'?1:0)+(['Service','Annat'].includes(c.alcohol)?1:0);
const filtered=()=>cards.filter(c=>!c.meterOnly&&(!filters.from||c.date>=filters.from)&&(!filters.to||c.date<=filters.to)&&(!filters.vehicle||c.vehicle===filters.vehicle)&&(!filters.driver||name(c)===filters.driver)&&(!filters.status||(filters.status==='open'?faults(c)>0&&!c.resolved:filters.status==='resolved'?faults(c)>0&&c.resolved:!faults(c))));
function message(text){let p=app.querySelector('#message');if(!p){p=document.createElement('p');p.id='message';p.setAttribute('role','alert');app.prepend(p)}p.className='notice';p.textContent=text}
function login(error=''){me=null;cards=[];config=null;document.querySelector('#logout').hidden=true;app.innerHTML=`<section class="panel login"><div class="eyebrow">ADMINISTRATION</div><h1>Logga in</h1><p>Förarna använder kontrollkorten utan lösenord. Här loggar arbetsledningen in.</p><form id="login"><label class="field">E-post<input name="email" type="email" autocomplete="username" required></label><label class="field">Lösenord<input name="password" type="password" autocomplete="current-password" required></label><p role="alert">${esc(error)}</p><button class="primary">Logga in →</button></form></section>`;app.querySelector('form').onsubmit=async e=>{e.preventDefault();const b=e.submitter;b.disabled=true;try{await api('login','POST',Object.fromEntries(new FormData(e.target)));await load()}catch(err){login(err.message)}}}
async function load(){me=await api('me');[cards,config,meterAdmin]=await Promise.all([api('cards'),api('config'),api('meter-status')]);document.querySelector('#logout').hidden=false;render()}
function filterForm(){return `<form id="filters" class="panel filter-grid"><label class="field">Från<input type="date" name="from" value="${esc(filters.from)}"></label><label class="field">Till<input type="date" name="to" value="${esc(filters.to)}"></label><label class="field">Fordon<select name="vehicle"><option value="">Alla fordon</option>${[...new Set([...config.vehicles.map(v=>v[0]),...cards.map(c=>c.vehicle)])].map(id=>`<option value="${esc(id)}" ${filters.vehicle===id?'selected':''}>${esc(config.vehicles.find(v=>v[0]===id)?.[1]||id)}${vehicleStatus(id,config)==='active'?'':' ('+vehicleStatusLabels[vehicleStatus(id,config)].toLowerCase()+')'}</option>`).join('')}</select></label><label class="field">Förare<select name="driver"><option value="">Alla förare</option>${[...new Set(cards.map(name))].sort().map(n=>`<option ${filters.driver===n?'selected':''}>${esc(n)}</option>`).join('')}</select></label><label class="field">Status<select name="status">${[['','Alla kontrollkort'],['open','Öppna fel'],['resolved','Åtgärdade fel'],['clear','Utan rapporterat fel']].map(([value,label])=>`<option value="${value}" ${filters.status===value?'selected':''}>${label}</option>`).join('')}</select></label><button>Filtrera</button></form>`}
function overview(){const rows=filtered(),open=rows.filter(c=>faults(c)&&!c.resolved),days=[...new Set(rows.map(c=>c.date))].sort().reverse();return `${filterForm()}<div class="stats">${[['Inskickade kort',rows.length],['Kort med öppna fel',open.length],['Fordon kontrollerade',new Set(rows.filter(c=>!c.meterOnly).map(c=>c.vehicle)).size],['Förare rapporterade',new Set(rows.map(name)).size]].map(([l,n])=>`<div class="panel"><strong>${n}</strong><span>${l}</span></div>`).join('')}</div><div class="panel"><h2>Kontroller per dag</h2>${days.length?days.map(d=>`<div class="record"><span>${esc(d)}</span><strong>${rows.filter(c=>c.date===d).length} kort</strong></div>`).join(''):'<p>Inga kontrollkort inom urvalet.</p>'}</div><div class="panel"><h2>Fordon utan kontroll idag</h2>${missingVehiclesToday()}<small>Visar aktiva fordon. Dolda fordon räknas inte här. Arbetsschema och krav på daglig användning är inte konfigurerade.</small></div><div class="actions"><h2>Kontrollkort</h2><button id="csv">Exportera urval (CSV)</button></div><div class="panel">${rows.length?rows.map(c=>`<div class="record"><div><strong>${esc(vehicle(c))}</strong><small>${esc(c.date)} · ${esc(name(c))}</small>${c.meterOnly?`<small>Mätarställning · ${esc(c.meterPeriod||c.date.slice(0,7))}</small>`:''}<span class="report-status ${faults(c)?(c.resolved?'report-status-resolved':'report-status-open'):'report-status-clear'}"><span aria-hidden="true">${faults(c)?(c.resolved?'✓':'!'):'✓'}</span> ${faults(c)?(c.resolved?'Åtgärdat':'Öppet fel'):'Utan rapporterat fel'}</span></div><button data-card="${esc(c.id)}">Visa →</button></div>`).join(''):'<p>Inga inskickade kontrollkort ännu.</p>'}</div>`}

function missingVehiclesToday(){const today=stockholmDate(),missing=config.vehicles.filter(v=>!(config.hiddenVehicles||[]).includes(v[0])&&!cards.some(c=>!c.meterOnly&&c.vehicle===v[0]&&c.date===today));return missing.length?`<ul class="missing-vehicles">${missing.map(v=>`<li><strong>${esc(v[1])}</strong><span>${esc(v[2])}</span></li>`).join('')}</ul>`:'<p>Alla aktiva fordon har en kontroll registrerad idag.</p>'}

const unitOptions=unit=>Object.entries(vehicleUnitNames).map(([id,label])=>`<option value="${id}" ${unit===id?'selected':''}>${label}</option>`).join('');
const typeOptions=type=>Object.entries(groupsFor(config)).map(([key,label])=>`<option value="${key}" ${key===type?'selected':''}>${esc(label.name)}</option>`).join('');
function driversEditor(){return `<section class="panel"><h2>Förarlista</h2><p>Förarna väljer namn utan inloggning eller identitetskontroll.</p><form id="settings"><label class="field">Ett namn per rad, inklusive Övrigt<textarea name="names" rows="12">${esc(config.names.join('\n'))}</textarea></label><button class="primary">Spara förarlista</button></form></section>`}
function settings(){const counts={active:0,hidden:0,'handed-over':0};config.vehicles.forEach(v=>counts[vehicleStatus(v[0],config)]++);return `<section class="panel"><h2>Lägg till nytt fordon</h2><p>Skapa ett nytt fordon när ett annat ersätts. Markera sedan det gamla fordonet som Överlämnat. Tidigare kontrollkort behåller sina uppgifter.</p><form id="add-vehicle"><div class="fields"><label class="field">Fordonsnamn<input name="title" maxlength="150" required></label><label class="field">Registrering / maskinnummer<input name="registration" maxlength="150" required></label><label class="field">Fordonsgrupp<select name="type" required>${typeOptions('loader')}</select></label><label class="field">Mätarenhet<select name="meterUnit">${unitOptions('timmar')}</select></label></div><p>Menyer och kontrollpunkter följer vald fordonsgrupp. När fordonet har skapats hanterar du bilden i samma fordonskort.</p><button class="primary">Skapa nytt fordon</button><p role="status"></p></form></section><section class="panel"><h2>Fordon (${counts.active} aktiva · ${counts.hidden} dolda · ${counts['handed-over']} överlämnade)</h2><p>Aktivt: kan väljas av förarna. Dolt: tillfälligt undangömt. Överlämnat: lämnat verksamheten. Dolda och överlämnade fordon finns kvar i statistik och historik och kan återaktiveras.</p><div class="fleet-register">${config.vehicles.map(v=>`<article class="fleet-vehicle-card" data-vehicle-card="${esc(v[0])}"><div class="sectiontitle"><h3>${esc(v[1])}</h3><span class="vehicle-status vehicle-status-${vehicleStatus(v[0],config)}">${vehicleStatusLabels[vehicleStatus(v[0],config)]}</span></div><div class="fleet-vehicle-body">${imageEditor(v)}<form class="fleet-editor" data-fleet-id="${esc(v[0])}"><h4>Fordonsuppgifter</h4><div class="fields"><label class="field">Fordonsnamn<input name="title" value="${esc(v[1])}" maxlength="150" required></label><label class="field">Registrering / maskinnummer<input name="registration" value="${esc(v[2])}" maxlength="150" required></label><label class="field">Fordonsgrupp<select name="type">${typeOptions(v[3])}</select></label><label class="field">Mätarenhet<select name="meterUnit">${unitOptions(vehicleUnit(v,config))}</select></label><label class="field">Status<select name="status">${Object.entries(vehicleStatusLabels).map(([id,label])=>`<option value="${id}" ${vehicleStatus(v[0],config)===id?'selected':''}>${label}</option>`).join('')}</select></label></div><div class="actions fleet-save-actions"><p role="status"></p><button type="submit" class="primary">Spara fordonsuppgifter</button></div></form></div></article>`).join('')}</div></section>`}

const adminSections=[
 {title:'Uppföljning',items:[['overview','Kontrollkort','Inskickade fordonskontroller och uppföljning av rapporterade fel.'],['statistics','Km & maskintimmar','Månadsavläsningar, användning och årsöversikt.'],['maintenance','Service & reparation','Service, reparationer och inspektioner. Dessa betraktas tills vidare som demodata.'],['meter','Mätarrapportering','Sista arbetsdagar, kommentarer och bevakning av saknade avläsningar.']]},
 {title:'Fordonsinställningar',items:[['settings','Fordon & bilder','Skapa, redigera eller dölj fordon och hantera deras bilder.'],['groups','Fordonsgrupper','Bestäm vilka kontrollsektioner som är aktiva för varje grupp.'],['questions','Kontrollfrågor','Redigera, ordna och visa eller dölj sektioner och frågor per fordonsgrupp.'],['equipment','Extrautrustning','Redigera valfria utrustningslistor per fordon.']]},
 {title:'Administration',items:[['drivers','Förare','Hantera namnen som förarna kan välja i kontrollkortet.'],['page','Sidtexter','Redigera rubriker och texter på förarsidan med förhandsgranskning.'],['accounts','Administratörer','Hantera konton för arbetsledningen.']]}
];
function render(){const sections=adminSections.map(g=>({...g,items:g.items.filter(([id])=>allowedAdminTab(me,id))})).filter(g=>g.items.length);if(!sections.some(g=>g.items.some(([id])=>id===tab)))tab='overview';if(location.hash!=='#'+tab){const url=new URL(location.href);url.hash=tab;history.replaceState(null,'',url)};const current=sections.flatMap(g=>g.items).find(([id])=>id===tab);app.innerHTML=`<div class="admin-intro"><div class="admin-intro-copy"><div class="eyebrow">QFSV · ARBETSLEDNING</div><h1>Överblick & administration</h1><p>Inloggad som ${esc(me.email)} <span class="account-role">${esc(accountRoles[me.role]||'User')}</span></p></div>${tab==='accounts'&&canManageAccounts(me)?'<aside class="admin-app-qr" aria-label="QR-kod till QFSV-appen"><a href="./app-qr.png" download="QFSV-app-qr.png" aria-label="Hämta QR-koden som PNG"><img src="./app-qr.svg" width="144" height="144" alt="QR-kod till https://kon.qfsv.workers.dev/"></a><div><strong>Öppna QFSV-appen</strong><a href="https://kon.qfsv.workers.dev/">kon.qfsv.workers.dev</a><a href="./app-qr.png" download="QFSV-app-qr.png">Hämta QR-kod</a></div></aside>':''}</div><nav class="admin-tabs admin-menu" aria-label="Administration">${sections.map(g=>`<div class="admin-menu-group"><span class="admin-menu-label">${g.title}</span><div>${g.items.map(([id,label])=>`<button data-tab="${id}" class="${tab===id?'active':''}" ${tab===id?'aria-current="page"':''}>${label}</button>`).join('')}</div></div>`).join('')}</nav><label class="mobile-admin-menu field">Adminmeny<select id="mobile-admin-nav" aria-label="Välj sida i administrationen">${sections.map(g=>`<optgroup label="${g.title}">${g.items.map(([id,label])=>`<option value="${id}" ${tab===id?'selected':''}>${label}</option>`).join('')}</optgroup>`).join('')}</select></label><div class="admin-page-heading"><h2>${current[1]}</h2><p>${current[2]}</p></div><div id="content">${tab==='overview'?overview():tab==='statistics'?statisticsPage():tab==='maintenance'?maintenancePage():tab==='settings'?settings():tab==='drivers'?driversEditor():tab==='groups'?groupEditor():tab==='questions'?questionEditor():tab==='equipment'?equipmentEditor():tab==='meter'?meterEditor():tab==='page'?pageEditor():accountsPage()}</div>`;
app.querySelectorAll('[data-tab]').forEach(b=>b.onclick=()=>navigateTab(b.dataset.tab));app.querySelector('#mobile-admin-nav').onchange=e=>navigateTab(e.target.value);
if(tab==='overview'){app.querySelector('#filters').onsubmit=e=>{e.preventDefault();filters=Object.fromEntries(new FormData(e.target));render()};app.querySelectorAll('[data-card]').forEach(b=>b.onclick=()=>detail(cards.find(c=>c.id===b.dataset.card)));app.querySelector('#csv').onclick=csv}
if(tab==='statistics')bindStatistics();
if(tab==='maintenance')bindMaintenance();
if(tab==='groups')bindGroups();
if(tab==='questions')bindQuestionEditor();
if(tab==='equipment')bindEquipmentEditor();
if(tab==='meter')bindMeterEditor();
if(tab==='page')bindPageEditor();
if(tab==='settings'){bindFleet();bindPageEditor()}
if(tab==='drivers')bindFleet();
if(tab==='accounts')bindAccounts();
}
async function detail(c){app.innerHTML=`<button id="back">← Tillbaka</button><div class="panel"><h1>${esc(vehicle(c))}</h1><p>${esc(c.date)} · ${esc(name(c))}</p>${canEdit(me)?'<div class="actions"><button type="button" id="edit-report">Redigera rapport</button></div>':''}<div class="summary">${cardHtml(c,config.vehicles)}</div>${correctionHistory(c)}${canEdit(me)?`<h2>Arbetsledningens uppföljning</h2><form id="resolve"><label class="toggle"><input name="resolved" type="checkbox" ${c.resolved?'checked':''}>Rapporterade fel är åtgärdade</label><label class="field">Åtgärdsanteckning<textarea name="note">${esc(c.note)}</textarea></label><button class="primary">Spara uppföljning</button><p id="result" role="status"></p></form><section class="report-delete"><h2>Radera rapport</h2><p>Rapporten tas bort permanent, inklusive mätarställning och eventuell underhållsanteckning. Statistik och rapporteringsstatus räknas om.</p><button type="button" id="delete-report" class="danger">Radera rapport</button></section>`:`<h2>Arbetsledningens uppföljning</h2><p>${esc(c.note||'Ingen åtgärdsanteckning.')}</p><p class="notice">Ditt konto har endast läsbehörighet.</p>`}</div>`;app.querySelector('#back').onclick=render;if(!canEdit(me))return;app.querySelector('#edit-report').onclick=()=>editReport(c);app.querySelector('#resolve').onsubmit=async event=>{event.preventDefault();const body={resolved:event.target.elements.resolved.checked,note:event.target.elements.note.value};try{await api('cards/'+c.id,'PATCH',body);Object.assign(c,body);app.querySelector('#result').textContent='Uppföljningen har sparats.'}catch(err){message(err.message)}};app.querySelector('#delete-report').onclick=async e=>{const button=e.currentTarget;button.disabled=true;if(!await confirmReportDeletion(c)){button.disabled=false;button.focus();return}try{await api('cards/'+encodeURIComponent(c.id),'DELETE',{confirmId:c.id})}catch(err){button.disabled=false;message(err.message);return}cards=cards.filter(row=>row.id!==c.id);try{meterAdmin=await api('meter-status')}catch{}render();message('Rapporten har raderats. Statistik och export använder de kvarvarande uppgifterna.')} }
function correctionHistory(c){return c.corrections?.length?`<details class="correction-history"><summary>Ändringshistorik (${c.corrections.length})</summary>${[...c.corrections].reverse().map(r=>`<section><strong>${esc(new Date(r.at).toLocaleString('sv-SE'))} · ${esc(r.by)}</strong><p>${esc(r.reason)}</p><dl>${Object.values(r.changes).map(change=>`<div><dt>${esc(change.label)}</dt><dd><del><span class="${isDeviation(change.from)?'deviation':''}">${esc(change.from||'Tomt')}</span></del> → <strong><span class="${isDeviation(change.to)?'deviation':''}">${esc(change.to||'Tomt')}</span></strong></dd></div>`).join('')}</dl></section>`).join('')}</details>`:''}
function editReport(c){if(!canEdit(me))return detail(c);const fields=reportFields(c,config);const field=f=>`<label class="field">${esc(f.label)}${f.options?`<select class="${f.key!=='serviceType'&&isDeviation(f.value)?'deviation':''}" name="${esc(f.key)}">${f.options.map(([id,label])=>`<option value="${esc(id)}" ${f.value===id?'selected':''}>${esc(label)}</option>`).join('')}</select>`:f.type==='textarea'?`<textarea name="${esc(f.key)}" maxlength="5000">${esc(f.value)}</textarea>`:`<input type="${f.type||'text'}" name="${esc(f.key)}" value="${esc(f.value)}" ${f.key==='meterPeriod'?'':'required'} ${f.type==='number'?'min="0" step="any"':'maxlength="500"'}>`}</label>`;
 app.innerHTML=`<button id="cancel-edit-top">← Tillbaka till rapporten</button><section class="panel report-editor"><h1>Redigera rapport</h1><p>${esc(vehicle(c))} · ${esc(c.date)}</p><p class="notice">Rätta de inskickade uppgifterna. De ursprungliga kontrollfrågorna behålls även om du ändrar fordon. Alla ändringar sparas med orsak, tidpunkt och ditt administratörskonto.</p><form id="edit-report-form"><div class="fields">${fields.map(field).join('')}</div><label class="field">Orsak till rättningen<textarea name="reason" required maxlength="1000" placeholder="Till exempel: mätarställningen skrevs fel"></textarea></label><p id="edit-report-error" class="error" hidden role="alert"></p><div class="actions"><button type="button" id="cancel-edit">Avbryt</button><button class="primary" type="submit">Spara rättning</button></div></form></section>`;
 app.querySelectorAll('#edit-report-form select').forEach(el=>el.onchange=()=>el.classList.toggle('deviation',el.name!=='serviceType'&&isDeviation(el.value)));
 const cancel=()=>detail(c);app.querySelector('#cancel-edit').onclick=cancel;app.querySelector('#cancel-edit-top').onclick=cancel;
 app.querySelector('#edit-report-form').onsubmit=async e=>{e.preventDefault();const form=e.target,button=e.submitter,values=Object.fromEntries(new FormData(form)),reason=values.reason;delete values.reason;button.disabled=true;app.querySelector('#edit-report-error').hidden=true;try{const updated=await api('cards/'+encodeURIComponent(c.id),'PUT',{baseVersion:reportVersion(c),reason,fields:values});Object.assign(c,updated);try{meterAdmin=await api('meter-status')}catch{}await detail(c);message('Rättningen har sparats. Statistik och export är uppdaterade.')}catch(err){const error=app.querySelector('#edit-report-error');error.textContent=err.message;error.hidden=false;button.disabled=false}};
}

function confirmReportDeletion(c){const registration=c.snapshot?.vehicle?.[2]||config.vehicles.find(v=>v[0]===c.vehicle)?.[2]||'';
 const dialog=document.createElement('dialog');dialog.className='app-dialog delete-dialog';dialog.setAttribute('aria-labelledby','delete-dialog-title');dialog.setAttribute('aria-describedby','delete-dialog-description');
 dialog.innerHTML=`<form method="dialog"><div class="delete-dialog-top"><span class="delete-dialog-icon" aria-hidden="true">!</span><button type="submit" value="cancel" class="delete-dialog-close" aria-label="Stäng dialog">×</button></div><h2 id="delete-dialog-title">Radera rapport?</h2><p id="delete-dialog-description">Rapporten tas bort permanent. Kontrollera att du har valt rätt rapport.</p><div class="delete-dialog-report"><strong>${esc(vehicle(c))}</strong><span>${esc(registration)}</span><dl><div><dt>Datum</dt><dd>${esc(c.date)}</dd></div><div><dt>Förare</dt><dd>${esc(name(c))}</dd></div>${c.meter?`<div><dt>Mätarställning</dt><dd>${esc(c.reading)} ${esc(c.unit)}</dd></div>`:''}</dl></div><p class="delete-dialog-warning">Detta kan inte ångras. Statistik och rapporteringsstatus påverkas.</p><div class="delete-dialog-actions"><button type="submit" value="cancel" autofocus>Avbryt</button><button type="submit" value="delete" class="delete-confirm">Radera rapport</button></div></form>`;
 app.append(dialog);return new Promise(resolve=>{dialog.addEventListener('close',()=>{const confirmed=dialog.returnValue==='delete';dialog.remove();resolve(confirmed)},{once:true});dialog.showModal()});
}

function csv(){const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const rows=[['Datum','Förare','Fordon','Felantal','Åtgärdat','Åtgärdsanteckning'],...filtered().map(c=>[c.date,name(c),vehicle(c),faults(c),c.resolved?'Ja':'Nej',c.note])];const url=URL.createObjectURL(new Blob(['\uFEFF'+rows.map(r=>r.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='qfsv-kontrollkort.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)}
document.querySelector('#logout').onclick=async()=>{try{await api('logout','POST',{});login()}catch(err){message(err.message)}};


function pageEditor(){const values={...defaults,...config.content};return `<section class="panel"><h2>Texter på förarsidan</h2><p>Ändra texterna, förhandsgranska och spara när du är nöjd. Ändringarna visas för förarna när de öppnar eller laddar om sidan.</p><form id="page-texts"><div class="fields">${Object.entries(textFields).map(([key,[label]])=>`<label class="field">${esc(label)}<textarea name="${key}" required maxlength="1000">${esc(values[key])}</textarea></label>`).join('')}</div><div class="actions"><button type="button" id="preview-page">Förhandsgranska</button><button class="primary">Spara sidtexter</button></div><p id="text-result" role="status"></p></form><div id="page-preview" hidden><h3 id="preview-state">Förhandsgranskning</h3><p id="preview-loading" role="status"></p><iframe id="preview-frame" title="Förhandsgranskning av förarsidan" src="about:blank"></iframe></div></section>`}
function imageEditor(v){return `<form class="image-editor" data-image-id="${esc(v[0])}"><img src="./api/images/${encodeURIComponent(v[0])}?v=${Date.now()}" alt="Bild av ${esc(v[1])}"><label class="field">Standardbild för återställning<select name="defaultModel"><option value="">Automatiskt standardval</option>${Object.keys(modelImages).map(id=>`<option value="${id}" ${(config.imageDefaults?.[v[0]]||v[0])===id?'selected':''}>${esc((id==='crafter'?'VW Crafter – påbyggnadsskåp med takspoiler':id==='crafter_panel'?'VW Crafter – tidigare skåpbild':'')||stockVehicles.find(x=>x[0]===id)?.[1]||(id==='transporter'?'VW e-Transporter Crew Cab':id==='transporter_t61'?'VW Transporter T6.1 (äldre kaross)':id))}</option>`).join('')}</select></label><button type="button" data-default>Spara standardval</button><p class="sub">Standardvalet används när du återställer bilden. En egen uppladdad bild behålls tills dess.</p><label class="field">Välj ny bild<input name="image" type="file" accept="image/png,image/jpeg,image/webp"></label><div class="actions"><button class="primary" type="submit" disabled>Spara bild</button><button type="button" data-restore>Återställ standardbild</button></div><p role="status"></p></form>`}

function bindPageEditor(){
 const form=app.querySelector('#page-texts');if(form){const getContent=()=>Object.fromEntries(new FormData(form));
 const frame=app.querySelector('#preview-frame'),loading=app.querySelector('#preview-loading'),heading=app.querySelector('#preview-state');
 const previewTitle=()=>heading.textContent=JSON.stringify(getContent())===JSON.stringify({...defaults,...config.content})?'Förhandsgranskning – sparade sidtexter':'Förhandsgranskning – osparade sidtexter';
 const send=()=>{if(!form.isConnected||frame.dataset.ready!=='1')return;frame.contentWindow.postMessage({type:'QFSV_PREVIEW',content:getContent()},location.origin);previewTitle();loading.textContent=''};
 frame.addEventListener('qfsv:preview-ready',send);
 const preview=()=>{if(!form.reportValidity())return;app.querySelector('#page-preview').hidden=false;previewTitle();if(frame.dataset.ready==='1'){send();return}loading.textContent='Laddar förhandsgranskning…';frame.src='./?preview=1';};
 app.querySelector('#preview-page').onclick=preview;
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const status=app.querySelector('#text-result');try{const content=getContent();await api('content','PUT',content);config.content=content;if(!app.querySelector('#page-preview').hidden){previewTitle();send()}status.textContent='Sidtexterna har sparats. Ladda om förarsidan för att se ändringarna.'}catch(err){status.textContent=err.message}finally{button.disabled=false}};
 }
 app.querySelectorAll('[data-image-id]').forEach(editor=>{let pending=null;const input=editor.elements.image,img=editor.querySelector('img'),status=editor.querySelector('[role=status]'),save=editor.querySelector('[type=submit]'),restore=editor.querySelector('[data-restore]');
 input.onchange=async()=>{pending=null;save.disabled=true;status.textContent='';const file=input.files[0];if(!file)return;try{if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>15000000)throw new Error('Välj PNG, JPEG eller WebP på högst 15 MB.');const image=await createImageBitmap(file);try{if(image.width>12000||image.height>12000)throw new Error('Bilden är för stor. Välj högst 12000 pixlar per sida.');const scale=Math.min(1,1200/Math.max(image.width,image.height));const canvas=document.createElement('canvas');canvas.width=Math.max(1,Math.round(image.width*scale));canvas.height=Math.max(1,Math.round(image.height*scale));canvas.getContext('2d').drawImage(image,0,0,canvas.width,canvas.height);const blob=await new Promise(resolve=>canvas.toBlob(resolve,'image/webp',0.82));if(!blob||blob.size>500000)throw new Error('Bilden blev för stor. Välj en mindre bild.');const data=await new Promise((resolve,reject)=>{const reader=new FileReader();reader.onload=()=>resolve(reader.result);reader.onerror=reject;reader.readAsDataURL(blob)});img.src=data;pending={type:blob.type,data:data.split(',')[1]};save.disabled=false;status.textContent='Förhandsgranskning – klicka Spara bild för att använda bilden.'}finally{image.close()}}catch(err){status.textContent=err.message||'Bilden kunde inte läsas.'}};
 editor.onsubmit=async e=>{e.preventDefault();if(!pending)return;save.disabled=true;input.disabled=true;restore.disabled=true;try{await api('images/'+encodeURIComponent(editor.dataset.imageId),'PUT',pending);pending=null;input.value='';img.src='./api/images/'+encodeURIComponent(editor.dataset.imageId)+'?v='+Date.now();status.textContent='Fordonsbilden har sparats.'}catch(err){status.textContent=err.message;save.disabled=false}finally{input.disabled=false;restore.disabled=false}};
 editor.querySelector('[data-default]').onclick=async e=>{const button=e.currentTarget;button.disabled=true;try{const model=editor.elements.defaultModel.value;await api('image-defaults/'+encodeURIComponent(editor.dataset.imageId),'PUT',{model});config.imageDefaults={...config.imageDefaults};if(model)config.imageDefaults[editor.dataset.imageId]=model;else delete config.imageDefaults[editor.dataset.imageId];img.src='./api/images/'+encodeURIComponent(editor.dataset.imageId)+'?v='+Date.now();status.textContent='Standardvalet har sparats. Klicka Återställ standardbild för att ersätta en egen uppladdad bild.'}catch(err){status.textContent=err.message}finally{button.disabled=false}};
 restore.onclick=async()=>{restore.disabled=true;try{await api('images/'+encodeURIComponent(editor.dataset.imageId),'DELETE',{});pending=null;input.value='';save.disabled=true;img.src='./api/images/'+encodeURIComponent(editor.dataset.imageId)+'?v='+Date.now();status.textContent='Standardbilden används. Välj en modell ovan om fordonet saknar en standardbild.'}catch(err){status.textContent=err.message}finally{restore.disabled=false}};
 });
}

async function saveFleet(value){await api('config','PUT',value);config=value}
function bindFleet(){
 const driverForm=app.querySelector('#settings');if(driverForm)driverForm.onsubmit=async e=>{e.preventDefault();try{const names=new FormData(e.target).get('names').split('\n').map(n=>n.trim()).filter(Boolean);await saveFleet({...config,names});message('Förarlistan har sparats.')}catch(err){message(err.message)}};
 const vehicleForm=app.querySelector('#add-vehicle');if(vehicleForm)vehicleForm.elements.type.onchange=()=>vehicleForm.elements.meterUnit.value=vehicleUnit(['','','',vehicleForm.elements.type.value]);if(vehicleForm)vehicleForm.onsubmit=async e=>{e.preventDefault();const form=e.target,button=e.submitter;button.disabled=true;try{const f=new FormData(form),id='v-'+crypto.randomUUID();const next=[id,f.get('title').trim(),f.get('registration').trim(),f.get('type')];await saveFleet({...config,vehicles:[...config.vehicles,next],vehicleUnits:{...config.vehicleUnits,[id]:f.get('meterUnit')}});render();message('Det nya fordonet är skapat och kan väljas av förarna. Du kan nu lägga till en bild.')}catch(err){form.querySelector('[role=status]').textContent=err.message;button.disabled=false}};
 app.querySelectorAll('[data-fleet-id]').forEach(form=>{const id=form.dataset.fleetId;
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const f=new FormData(form),updated=[id,f.get('title').trim(),f.get('registration').trim(),f.get('type')];const status=f.get('status'),hiddenVehicles=(config.hiddenVehicles||[]).filter(x=>x!==id),handedOverVehicles=(config.handedOverVehicles||[]).filter(x=>x!==id);if(status!=='active')hiddenVehicles.push(id);if(status==='handed-over')handedOverVehicles.push(id);await saveFleet({...config,vehicles:config.vehicles.map(v=>v[0]===id?updated:v),hiddenVehicles,handedOverVehicles,vehicleUnits:{...config.vehicleUnits,[id]:f.get('meterUnit')}});form.querySelector('[role=status]').textContent='Fordonsuppgifter och status har sparats.';const card=form.closest('.fleet-vehicle-card');card.querySelector('h3').textContent=updated[1];card.querySelector('img').alt='Bild av '+updated[1];const badge=card.querySelector('.vehicle-status');badge.className='vehicle-status vehicle-status-'+status;badge.textContent=vehicleStatusLabels[status];const title=form.closest('section').querySelector('h2'),counts={active:0,hidden:0,'handed-over':0};config.vehicles.forEach(v=>counts[vehicleStatus(v[0],config)]++);title.textContent='Fordon ('+counts.active+' aktiva · '+counts.hidden+' dolda · '+counts['handed-over']+' överlämnade)'}catch(err){form.querySelector('[role=status]').textContent=err.message}finally{button.disabled=false}};

 });
}

function groupEditor(){const groups=groupsFor(config);return `<section class="panel"><h2>Grupper & menyregler</h2><p>Bestäm vilka menyer som ska visas för varje fordonsgrupp. Välj sedan grupp på respektive fordon under Fordon & bilder. Reglerna gäller nya kontroller; tidigare inskickade kort behåller sina uppgifter.</p><form id="group-rules">${Object.entries(groups).map(([id,group])=>`<fieldset class="group-rule" data-group="${id}"><legend>${esc(group.name)}</legend><label class="field">Gruppnamn<input name="${id}-name" value="${esc(group.name)}" maxlength="100" required></label><div class="group-toggles">${Object.entries(menuOptions).map(([key,label])=>`<label class="toggle"><input type="checkbox" name="${id}-${key}" ${group[key]?'checked':''}>${esc(label)}</label>`).join('')}</div><p class="sub">${config.vehicles.filter(v=>v[3]===id).map(v=>esc(v[1])).join(' · ')||'Inga fordon i gruppen ännu.'}</p></fieldset>`).join('')}<button class="primary">Spara gruppregler</button><p id="group-result" role="status"></p></form></section>`}
function bindGroups(){app.querySelector('#group-rules').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;const form=e.target;try{const groups=Object.fromEntries(Object.keys(groupsFor(config)).map(id=>[id,{name:form.elements[id+'-name'].value.trim(),...Object.fromEntries(Object.keys(menuOptions).map(key=>[key,form.elements[id+'-'+key].checked]))}]));await api('groups','PUT',groups);config.groups=groups;app.querySelectorAll('[data-group]').forEach(el=>el.querySelector('legend').textContent=groups[el.dataset.group].name);app.querySelector('#group-result').textContent='Gruppreglerna är sparade. Förarna ser dem när sidan laddas om.'}catch(err){app.querySelector('#group-result').textContent=err.message}finally{button.disabled=false}}}

let editingGroup='tractor',editingSections=null,questionDrafts={};
const representative=group=>config.vehicles.find(v=>v[3]===group)||['','','',group];
function questionEditor(){if(!editingSections)editingSections=structuredClone(sectionsFor(representative(editingGroup),config));return `<section class="panel"><h2>Sektioner & frågor</h2><p>Välj fordonsgrupp. Redigera rubriker och frågor, flytta med pilarna och välj vad som ska visas. Spara när du är klar. Gamla kontrollkort behåller de frågor som gällde vid inskick.</p><label class="field">Fordonsgrupp<select id="question-group">${Object.entries(groupsFor(config)).map(([id,g])=>`<option value="${id}" ${id===editingGroup?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label><p class="notice">Gruppens menyregler gäller också. En sektion måste vara aktiverad både här och under Grupper & menyregler för att visas.</p><form id="question-editor"><div id="sections-list"></div><div class="actions"><button type="button" id="add-section">+ Ny sektion med frågor</button><button class="primary">Spara sektioner och frågor</button></div><p id="questions-result" role="status"></p></form></section>`}
function bindQuestionEditor(){
 const list=app.querySelector('#sections-list'),form=app.querySelector('#question-editor');
 const draw=()=>{list.innerHTML=editingSections.map((s,i)=>`<fieldset class="section-editor" data-section="${s.id}"><legend>${i+1}. ${esc(s.title)}</legend><div class="reorder-actions"><button type="button" data-move-section="${i}" data-direction="-1" aria-label="Flytta sektionen upp" ${i===0?'disabled':''}>↑ Upp</button><button type="button" data-move-section="${i}" data-direction="1" aria-label="Flytta sektionen ner" ${i===editingSections.length-1?'disabled':''}>↓ Ner</button>${s.type==='custom'?`<button type="button" data-remove-section="${i}">Ta bort sektion</button>`:''}</div><label class="field">Sektionens rubrik<input data-title="${i}" value="${esc(s.title)}" maxlength="200" required></label><label class="toggle"><input type="checkbox" data-section-visible="${i}" ${s.visible?'checked':''}>Visa sektionen</label>${['daily','weekly','vehicleStatus','custom'].includes(s.type)?`<div class="question-edit-list">${s.questions.map((q,j)=>`<div class="question-edit-row"><label class="field">Fråga ${j+1}<input data-question="${i}:${j}" value="${esc(q.text)}" maxlength="500" required></label><label class="toggle"><input type="checkbox" data-question-visible="${i}:${j}" ${q.visible?'checked':''}>Visa</label><div class="reorder-actions"><button type="button" data-move-question="${i}:${j}" data-direction="-1" aria-label="Flytta frågan upp" ${j===0?'disabled':''}>↑</button><button type="button" data-move-question="${i}:${j}" data-direction="1" aria-label="Flytta frågan ner" ${j===s.questions.length-1?'disabled':''}>↓</button><button type="button" data-remove-question="${i}:${j}" aria-label="Ta bort frågan">Ta bort</button></div></div>`).join('')}</div><button type="button" data-add-question="${i}" ${s.questions.length>=80?'disabled':''}>+ Lägg till fråga</button>`:`<p class="sub">${s.type==='equipment'?'Redigera listan för respektive fordon under fliken Extrautrustning.':'Denna sektion använder appens fasta fält. Lägg till en egen sektion för fler kontrollfrågor.'}</p>`}</fieldset>`).join('')};
 draw();
 const pair=value=>value.split(':').map(Number);
 form.oninput=e=>{const el=e.target;if(el.dataset.title!==undefined){editingSections[+el.dataset.title].title=el.value;el.closest('fieldset').querySelector('legend').textContent=(+el.dataset.title+1)+'. '+el.value}if(el.dataset.question!==undefined){const [i,j]=pair(el.dataset.question);editingSections[i].questions[j].text=el.value}if(el.dataset.sectionVisible!==undefined)editingSections[+el.dataset.sectionVisible].visible=el.checked;if(el.dataset.questionVisible!==undefined){const [i,j]=pair(el.dataset.questionVisible);editingSections[i].questions[j].visible=el.checked}};
 const move=(array,index,direction)=>{const target=index+direction;if(target>=0&&target<array.length)[array[index],array[target]]=[array[target],array[index]]};
 form.onclick=e=>{const b=e.target.closest('button');if(!b)return;
 if(b.dataset.moveSection!==undefined){move(editingSections,+b.dataset.moveSection,+b.dataset.direction);draw()}
 if(b.dataset.moveQuestion!==undefined){const [i,j]=pair(b.dataset.moveQuestion);move(editingSections[i].questions,j,+b.dataset.direction);draw()}
 if(b.dataset.removeQuestion!==undefined){const [i,j]=pair(b.dataset.removeQuestion);editingSections[i].questions.splice(j,1);draw()}
 if(b.dataset.addQuestion!==undefined){editingSections[+b.dataset.addQuestion].questions.push({id:'q_'+crypto.randomUUID(),text:'Ny kontrollfråga',visible:true});draw()}
 if(b.dataset.removeSection!==undefined){editingSections.splice(+b.dataset.removeSection,1);draw()}
 };
 app.querySelector('#add-section').onclick=()=>{if(editingSections.length>=25){app.querySelector('#questions-result').textContent='Högst 25 sektioner per grupp.';return}editingSections.push({id:'section-'+crypto.randomUUID(),type:'custom',title:'Ny sektion',visible:true,questions:[{id:'q_'+crypto.randomUUID(),text:'Ny kontrollfråga',visible:true}]});draw()};
 app.querySelector('#question-group').onchange=e=>{questionDrafts[editingGroup]=editingSections;editingGroup=e.target.value;editingSections=questionDrafts[editingGroup]||structuredClone(sectionsFor(representative(editingGroup),config));draw();app.querySelector('#questions-result').textContent='Visar frågor för '+groupsFor(config)[editingGroup].name+'.'};
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('forms/'+editingGroup,'PUT',editingSections);config.forms={...config.forms,[editingGroup]:structuredClone(editingSections)};app.querySelector('#questions-result').textContent='Sektioner och frågor har sparats. Förarna ser ändringarna när de laddar om sidan.'}catch(err){app.querySelector('#questions-result').textContent=err.message}finally{button.disabled=false}};
}

let equipmentVehicle=null,equipmentDrafts={};
function equipmentEditor(){if(!config.vehicles.some(v=>v[0]===equipmentVehicle))equipmentVehicle=config.vehicles[0]?.[0];return `<section class="panel"><h2>Redigera extrautrustning</h2><p>Välj vilket fordons utrustningslista du vill ändra. Lägg till, ändra namn, flytta, visa eller dölj poster. Gamla kontrollkort behåller sina ursprungliga utrustningsnamn och svar.</p><label class="field">Utrustningsfordon<select id="equipment-vehicle">${config.vehicles.map(v=>`<option value="${esc(v[0])}" ${equipmentVehicle===v[0]?'selected':''}>${esc(v[1])} · ${esc(v[2])}${vehicleStatus(v[0],config)==='active'?'':' ('+vehicleStatusLabels[vehicleStatus(v[0],config)].toLowerCase()+')'}</option>`).join('')}</select></label><form id="equipment-editor"><div id="equipment-items"></div><div class="actions"><button type="button" id="add-equipment">+ Lägg till utrustning</button><button class="primary">Spara utrustningslista</button></div><p id="equipment-result" role="status"></p></form></section>`}
function bindEquipmentEditor(){
 const form=app.querySelector('#equipment-editor'),list=app.querySelector('#equipment-items'),selector=app.querySelector('#equipment-vehicle');
 const items=()=>equipmentDrafts[equipmentVehicle]??=structuredClone(equipmentFor(config.vehicles.find(v=>v[0]===equipmentVehicle),config));
 const draw=()=>{const values=items();list.innerHTML=values.length?values.map((q,i)=>`<div class="question-edit-row"><label class="field">Utrustning ${i+1}<input data-equipment-name="${i}" value="${esc(q.text)}" required maxlength="500"></label><label class="toggle"><input type="checkbox" data-equipment-visible="${i}" ${q.visible?'checked':''}>Visa</label><div class="reorder-actions"><button type="button" data-equipment-move="${i}" data-direction="-1" aria-label="Flytta utrustningen upp" ${i===0?'disabled':''}>↑ Upp</button><button type="button" data-equipment-move="${i}" data-direction="1" aria-label="Flytta utrustningen ner" ${i===values.length-1?'disabled':''}>↓ Ner</button><button type="button" data-equipment-remove="${i}">Ta bort</button></div></div>`).join(''):'<p>Ingen extrautrustning i denna lista. Lägg till en post för att börja.</p>';app.querySelector('#add-equipment').disabled=values.length>=100};draw();
 selector.onchange=()=>{equipmentVehicle=selector.value;draw();app.querySelector('#equipment-result').textContent=''};
 form.oninput=e=>{const el=e.target;if(el.dataset.equipmentName!==undefined)items()[+el.dataset.equipmentName].text=el.value;if(el.dataset.equipmentVisible!==undefined)items()[+el.dataset.equipmentVisible].visible=el.checked};
 form.onclick=e=>{const button=e.target.closest('button');if(!button)return;const values=items();if(button.dataset.equipmentMove!==undefined){const i=+button.dataset.equipmentMove,j=i+(+button.dataset.direction);if(j>=0&&j<values.length)[values[i],values[j]]=[values[j],values[i]];draw()}if(button.dataset.equipmentRemove!==undefined){values.splice(+button.dataset.equipmentRemove,1);draw()}};
 app.querySelector('#add-equipment').onclick=()=>{if(items().length<100)items().push({id:'e_'+crypto.randomUUID(),text:'Ny utrustning',visible:true});draw()};
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter,id=equipmentVehicle,value=structuredClone(items());button.disabled=true;selector.disabled=true;try{await api('equipment/'+encodeURIComponent(id),'PUT',value);config.equipmentLists={...config.equipmentLists,[id]:value};app.querySelector('#equipment-result').textContent='Utrustningslistan har sparats. Ändringarna visas när förarsidan laddas om.'}catch(err){app.querySelector('#equipment-result').textContent=err.message}finally{button.disabled=false;selector.disabled=false}};
}

function meterEditor(){scheduleDraft??=structuredClone(config.meterSchedule||[]).map(row=>({...row,savedDate:row.date}));return `<section class="panel"><h2>Sista arbetsdagar & mätarställning</h2><p>Ange sista arbetsdagen för varje månad och en kommentar till datumet. Bevakningen gäller alla aktiva fordon där mätarställning är aktiverad.</p><p class="notice">På angivet datum visas kommentaren i fordonskontrollen och mätarställning krävs. Saknade avläsningar fortsätter att påminnas om efter datumet. Påminnelserna visas i appen; inga sms eller e-post skickas.</p><form id="meter-schedule"><div id="meter-dates"></div><div class="actions"><button type="button" id="add-meter-date">+ Lägg till månadens sista arbetsdag</button><button class="primary">Spara datum och kommentarer</button></div><p id="meter-schedule-result" role="status"></p></form></section><section class="panel"><div class="actions"><h2>Bevakning per månad</h2><button id="refresh-meter-admin">Uppdatera status</button></div><p>Idag: ${esc(meterAdmin.today)} · Status beräknas från inskickade mätarställningar i databasen.</p>${meterAdmin.rows.length?meterAdmin.rows.map(r=>`<section class="meter-status-row"><h3>${esc(r.period)} · ${esc(r.date)} · ${r.due?(r.missing.length?(r.overdue?'Saknas – försenat':'Ska skickas idag'):'Alla inskickade'):'Kommande'}</h3><p>${esc(r.comment)}</p><p>${r.complete.length} inskickade · ${r.missing.length} ${r.due?'saknas':'kvar att skicka på datumet'}</p>${r.missing.length?`<p><strong>${r.due?'Saknas för:':'Omfattar:'}</strong> ${r.missing.map(id=>esc(config.vehicles.find(v=>v[0]===id)?.[1]||id)).join(', ')}</p>`:''}${r.complete.length?`<p>Inskickat: ${r.complete.map(id=>esc(config.vehicles.find(v=>v[0]===id)?.[1]||id)).join(', ')}</p>`:''}</section>`).join(''):'<p>Lägg till datum ovan för att börja bevaka mätarställningar.</p>'}</section>`}
function bindMeterEditor(){const list=app.querySelector('#meter-dates'),form=app.querySelector('#meter-schedule');const draw=()=>{list.innerHTML=scheduleDraft.map((row,i)=>`<div class="meter-date-editor"><label class="field">Sista arbetsdag<input type="date" data-meter-date="${i}" value="${esc(row.date)}" required></label><label class="field">Kommentar<textarea rows="1" data-meter-comment="${i}" maxlength="1000" placeholder="Valfri kommentar">${esc(row.comment)}</textarea></label><div class="meter-row-actions"><button type="button" class="primary" data-save-meter-comment="${i}" ${!row.savedDate||row.date!==row.savedDate?'disabled':''} title="${row.savedDate&&row.date===row.savedDate?'Spara kommentaren för detta datum':'Spara datumlistan först'}">Spara kommentar</button><button type="button" data-remove-meter-date="${i}" aria-label="Ta bort datum">Ta bort</button></div></div>`).join('')};draw();
 form.oninput=e=>{if(e.target.dataset.meterDate!==undefined){const i=+e.target.dataset.meterDate;scheduleDraft[i].date=e.target.value;form.querySelector('[data-save-meter-comment="'+i+'"]').disabled=!scheduleDraft[i].savedDate||scheduleDraft[i].savedDate!==e.target.value;}if(e.target.dataset.meterComment!==undefined)scheduleDraft[+e.target.dataset.meterComment].comment=e.target.value};
 form.onclick=async e=>{const save=e.target.closest('[data-save-meter-comment]');if(save){const row=scheduleDraft[+save.dataset.saveMeterComment];save.disabled=true;try{await api('meter-schedule/'+row.savedDate,'PATCH',{comment:row.comment});config.meterSchedule=config.meterSchedule.map(r=>r.date===row.savedDate?{...r,comment:row.comment}:r);meterAdmin=await api('meter-status');render();app.querySelector('#meter-schedule-result').textContent='Kommentaren för '+row.savedDate+' är sparad.'}catch(err){app.querySelector('#meter-schedule-result').textContent=err.message;save.disabled=false}return}const b=e.target.closest('[data-remove-meter-date]');if(b){scheduleDraft.splice(+b.dataset.removeMeterDate,1);draw()}};
 app.querySelector('#add-meter-date').onclick=()=>{if(scheduleDraft.length>=120){app.querySelector('#meter-schedule-result').textContent='Högst 120 månader.';return}scheduleDraft.push({date:'',comment:''});draw()};
 form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{const value=scheduleDraft.map(({date,comment})=>({date,comment}));await api('meter-schedule','PUT',value);config.meterSchedule=structuredClone(value).sort((a,b)=>a.date.localeCompare(b.date));scheduleDraft=structuredClone(config.meterSchedule).map(row=>({...row,savedDate:row.date}));meterAdmin=await api('meter-status');render();app.querySelector('#meter-schedule-result').textContent='Datum och kommentarer har sparats. Bevakningen är aktiv.'}catch(err){app.querySelector('#meter-schedule-result').textContent=err.message;button.disabled=false}};
 app.querySelector('#refresh-meter-admin').onclick=async e=>{e.target.disabled=true;try{meterAdmin=await api('meter-status');render()}catch(err){message(err.message);e.target.disabled=false}};
}

let statisticsFilters={year:stockholmDate().slice(0,4),vehicle:'',group:'',vehicles:null,showEmpty:false};
const number=v=>v===null?'—':new Intl.NumberFormat('sv-SE',{maximumFractionDigits:1}).format(v);
const statsData=()=>spreadsheetStatistics(cards,config,{...statisticsFilters,...(tab==='maintenance'?{vehicles:null}:{vehicle:''})});
function statisticsVehicles(){const fleet=new Map(config.vehicles.map(v=>[v[0],v]));for(const c of cards)if(!fleet.has(c.vehicle))fleet.set(c.vehicle,c.snapshot?.vehicle||[c.vehicle,c.vehicle,'','']);return [...fleet.values()]}
function statisticsPage(){const data=statsData(),years=[...new Set([stockholmDate().slice(0,4),...cards.flatMap(c=>[c.date?.slice(0,4),c.meterPeriod?.slice(0,4)]).filter(y=>/^\d{4}$/.test(y||''))])].sort().reverse();
 const chart=(label,unit,key,countKey)=>`<div class="panel"><h2>${label} per månad</h2>${data.months.map(m=>`<div class="monthly-chart-row"><span>${esc(sheetMonth(m.period).replace(/\s+\d{4}$/,''))}</span><meter min="0" max="${Math.max(1,...data.months.map(m=>m[key]))}" value="${m[key]}" aria-label="${esc(sheetMonth(m.period))}: ${m[countKey]?number(m[key])+' '+unit:'saknar beräkningsunderlag'}"></meter><span>${m[countKey]?number(m[key])+' '+unit:'—'}</span></div>`).join('')}</div>`;
 return `<h3>Årsöversikt</h3>${statisticsFilterForm(years)}<div class="stats">${[...(data.columns.some(c=>c.unit==='km')?[['Beräknade kilometer',number(data.totals.km)+' km']]:[]),...(data.columns.some(c=>c.unit==='timmar')?[['Beräknade maskintimmar',number(data.totals.hours)+' h']]:[])].map(([label,value])=>`<div class="panel"><strong>${value}</strong><span>${label}</span></div>`).join('')}</div><p class="sub">Öppna ett fordon för att se månadsvärden och mätarställningar. Användningen beräknas från två på varandra följande månadsavläsningar.</p>${statisticsCards(data)}<details class="panel statistics-details"><summary>Visa månadsdiagram</summary><div class="statistics-charts">${data.columns.some(c=>c.unit==='km')?chart('Kilometer','km','km','kmCount'):''}${data.columns.some(c=>c.unit==='timmar')?chart('Maskintimmar','h','hours','hoursCount'):''}</div></details>`}

function bindStatistics(){app.querySelector('#statistics-filters').onsubmit=e=>{e.preventDefault();const values=new FormData(e.target);statisticsFilters={...Object.fromEntries(values),vehicle:'',vehicles:values.getAll('vehicles'),showEmpty:e.target.elements.showEmpty?.checked??true};render()};app.querySelectorAll('[data-vehicle-selection]').forEach(button=>button.onclick=()=>{app.querySelectorAll('input[name=vehicles]').forEach(input=>input.checked=button.dataset.vehicleSelection==='all');updateVehicleCount()});const updateVehicleCount=()=>{const inputs=[...app.querySelectorAll('input[name=vehicles]')],label=app.querySelector('#vehicle-selection-count');if(label)label.textContent=inputs.filter(input=>input.checked).length+' av '+inputs.length+' fordon markerade'};app.querySelectorAll('input[name=vehicles]').forEach(input=>input.onchange=updateVehicleCount);updateVehicleCount();app.querySelectorAll('[data-statistics-card]').forEach(b=>b.onclick=()=>detail(cards.find(c=>c.id===b.dataset.statisticsCard)));const exportSheet=()=>{const data=statsData(),rows=data.rows.filter(r=>statisticsFilters.showEmpty||r.hasActivity);const allValues=spreadsheetCsvRows(data),cutoff=allValues.findIndex(r=>r[0]==='REGISTRERAD SERVICE / REPARATION'),values=cutoff<0?allValues:allValues.slice(0,cutoff-1);const safe=v=>{let s=String(v??'');if(/^[=+@\-\t\r\n]/.test(s))s="'"+s;return '"'+s.replaceAll('"','""')+'"'};const url=URL.createObjectURL(new Blob(['\uFEFF'+values.map(row=>row.map(safe).join(';')).join('\r\n')],{type:'text/csv;charset=utf-8'}));const a=document.createElement('a');a.href=url;a.download='qfsv-km-maskintimmar-'+statisticsFilters.year+'.csv';a.click();setTimeout(()=>URL.revokeObjectURL(url),1000)};app.querySelectorAll('[data-reading-card]').forEach(b=>b.onclick=()=>detail(cards.find(c=>c.id===b.dataset.readingCard)));app.querySelector('#sheet-csv').onclick=exportSheet;app.querySelector('#sheet-pdf').onclick=()=>{try{const data=statisticsPdf(statsData(),{year:statisticsFilters.year}),url=URL.createObjectURL(new Blob([data],{type:'application/pdf'})),a=document.createElement('a');a.href=url;a.download='qfsv-matarstallning-'+statisticsFilters.year+'.pdf';a.click();setTimeout(()=>URL.revokeObjectURL(url),60000)}catch(err){message(err.message)}};app.querySelector('#statistics-expand').onclick=e=>{const details=[...app.querySelectorAll('.vehicle-stat-card')],open=details.some(d=>!d.open);details.forEach(d=>d.open=open);e.target.textContent=open?'Fäll ihop månader':'Visa alla månadsrader'}}

const sheetMonth=period=>new Intl.DateTimeFormat('sv-SE',{month:'long',year:'numeric',timeZone:'UTC'}).format(new Date(period+'-01T12:00:00Z'));
function statisticsCards(data){const ids=[...new Set(data.columns.map(c=>c.vehicle))];return `<div class="statistics-toolbar"><button type="button" id="statistics-expand">Visa alla månadsrader</button><div class="statistics-export-actions"><button type="button" id="sheet-pdf" class="primary" ${data.columns.length?'':'disabled'}>Exportera PDF</button><button type="button" id="sheet-csv" ${data.columns.length?'':'disabled'}>CSV / Excel</button></div></div><div class="vehicle-stat-grid">${!ids.length?'<p class="notice">Inga fordon ingår i urvalet. Välj minst ett fordon och kontrollera vald fordonsgrupp.</p>':''}${ids.map(id=>{const columns=data.columns.map((col,index)=>({...col,index})).filter(c=>c.vehicle===id),v=columns[0],identity=vehicleIdentity([id,v.name,v.registration,v.group]);return `<details class="vehicle-stat-card" ${statisticsFilters.vehicle===id?'open':''}><summary><div class="vehicle-stat-heading"><span class="vehicle-stat-brand">${esc(identity.brand)}</span><strong>${esc(identity.model||v.name)}</strong><small>${esc(v.registration)}</small></div><div class="vehicle-stat-totals">${columns.map(c=>{const total=data.sheetTotals[c.index],unit=c.unit==='km'?'km':'h';return `<div><strong>${number(total.sum)} ${unit}</strong><small>${total.count?number(total.average)+' '+unit+'/månad · '+total.count+' mån':'Underlag saknas'}</small></div>`}).join('')}</div><span class="vehicle-stat-open">Månadsuppgifter <span aria-hidden="true">⌄</span></span></summary><div class="vehicle-stat-months"><div class="vehicle-stat-baseline"><strong>Startvärde · ${esc(sheetMonth(data.sheetReadings[0].period))}</strong>${columns.map(c=>{const value=data.sheetReadings[0].cells[c.index];return `<span>${value?number(value.value)+' '+(c.unit==='km'?'km':'h'):'Ingen avläsning'} ${value?.id?`<button type="button" class="reading-link" data-reading-card="${esc(value.id)}">Visa rapport</button>`:''}</span>`}).join('')}</div>${data.sheetConsumption.map(month=>{const read=data.sheetReadings.find(r=>r.period===month.period);return `<section class="vehicle-stat-month"><h3>${esc(sheetMonth(month.period))}</h3><div class="vehicle-month-values">${columns.map(c=>{const current=read?.cells[c.index],usage=month.cells[c.index],unit=c.unit==='km'?'km':'h';return `<div><span>Avläst ${unit}</span><strong>${current?number(current.value):'—'}</strong><small>${current?esc(current.date):'Ingen avläsning'}</small>${current?.id?`<button type="button" class="reading-link" data-reading-card="${esc(current.id)}">Visa rapport</button>`:''}</div><div class="${usage.status==='decreased'?'vehicle-stat-error':''}"><span>${c.unit==='km'?'Körda kilometer':'Drifttimmar'}</span><strong>${number(usage.value)}${usage.value===null?'':' '+unit}</strong><small>${usage.value===null?esc(readingStatus[usage.status]):'Under månaden'}</small></div>`}).join('')}</div></section>`}).join('')}</div></details>`}).join('')}</div>`}

function statisticsVehiclePicker(){const fleet=statisticsVehicles(),selected=Array.isArray(statisticsFilters.vehicles)?new Set(statisticsFilters.vehicles):null;return `<fieldset class="statistics-vehicle-picker"><legend>Välj fordon till statistik och export</legend><div class="statistics-selection-actions"><button type="button" data-vehicle-selection="all">Markera alla</button><button type="button" data-vehicle-selection="none">Avmarkera alla</button><span id="vehicle-selection-count" role="status">${fleet.filter(v=>!selected||selected.has(v[0])).length} av ${fleet.length} fordon markerade</span></div><div class="statistics-vehicle-options">${fleet.map(v=>`<label class="statistics-vehicle-option"><input type="checkbox" name="vehicles" value="${esc(v[0])}" ${(!selected||selected.has(v[0]))?'checked':''}><span>${esc(v[1])}<small>${esc(v[2])}${vehicleStatus(v[0],config)==='active'?'':' · '+esc(vehicleStatusLabels[vehicleStatus(v[0],config)])}</small></span></label>`).join('')}</div><p class="sub">Klicka på Visa statistik för att använda urvalet. Samma urval används i PDF och CSV/Excel. Fordonsgrupp och fordonsurval används tillsammans.</p></fieldset>`}
function statisticsFilterForm(years,label='Visa statistik'){return `<form id="statistics-filters" class="panel filter-grid"><label class="field">År<select name="year">${years.map(y=>`<option ${String(statisticsFilters.year)===y?'selected':''}>${y}</option>`).join('')}</select></label><label class="field">Fordonsgrupp<select name="group"><option value="">Alla grupper</option>${Object.entries(groupsFor(config)).map(([id,g])=>`<option value="${id}" ${statisticsFilters.group===id?'selected':''}>${esc(g.name)}</option>`).join('')}</select></label>${tab==='statistics'?statisticsVehiclePicker():`<label class="field">Fordon / maskin<select name="vehicle"><option value="">Alla fordon</option>${statisticsVehicles().map(v=>`<option value="${esc(v[0])}" ${statisticsFilters.vehicle===v[0]?'selected':''}>${esc(v[1])}${vehicleStatus(v[0],config)==='active'?'':' ('+vehicleStatusLabels[vehicleStatus(v[0],config)].toLowerCase()+')'}</option>`).join('')}</select></label>`}<button class="primary">${esc(label)}</button></form>`}
function maintenancePage(){const data=statsData(),years=[...new Set([stockholmDate().slice(0,4),...cards.filter(c=>c.service).map(c=>c.date.slice(0,4))])].sort().reverse();return `${statisticsFilterForm(years,'Visa historik')}<div class="notice">Service och reparationer visas som demodata tills vidare. Kilometer och maskintimmar finns under Km & maskintimmar.</div><section class="panel"><h2>Service- och reparationshistorik</h2><p class="sub">Demodata: uppgifterna kan avse planerade eller rapporterade arbeten och är inte bekräftelse på utförd service.</p>${data.events.length?data.events.map(c=>`<div class="record"><div><strong>${esc(c.serviceType)} · ${esc(vehicle(c))}</strong><small>${esc(c.date)} · ${esc(name(c))}</small><p>${esc(c.serviceComment||'')}</p></div><button data-statistics-card="${esc(c.id)}">Visa kort →</button></div>`).join(''):'<p>Ingen service eller reparation registrerad i urvalet.</p>'}</section>`}
function bindMaintenance(){app.querySelector('#statistics-filters').onsubmit=e=>{e.preventDefault();statisticsFilters={...statisticsFilters,...Object.fromEntries(new FormData(e.target))};render()};app.querySelectorAll('[data-statistics-card]').forEach(b=>b.onclick=()=>detail(cards.find(c=>c.id===b.dataset.statisticsCard)))}

const roleOptions=selected=>Object.entries(accountRoles).map(([id,label])=>`<option value="${id}" ${id===selected?'selected':''}>${label}</option>`).join('');
function accountsPage(){return `<section class="panel"><h2>Konton & roller</h2><div class="role-guide"><div><strong>Superadmin</strong><p>Full åtkomst, inklusive konton och roller.</p></div><div><strong>Admin</strong><p>Redigerar fordon, kontrollkort och inställningar. Hanterar inte konton.</p></div><div><strong>User</strong><p>Läser kontrollkort, statistik och underhåll. Kan inte ändra eller radera uppgifter.</p></div></div><div id="accounts"><p>Läser konton…</p></div></section><section class="panel"><h2>Skapa konto</h2><form id="account"><div class="fields"><label class="field">E-post<input name="email" type="email" autocomplete="off" required></label><label class="field">Roll<select name="role">${roleOptions('user')}</select></label><label class="field">Lösenord (minst 12 tecken)<input name="password" type="password" minlength="12" autocomplete="new-password" required></label></div><button class="primary">Skapa konto</button><p id="account-result" role="status"></p></form></section>`}
function bindAccounts(){
 api('admins').then(accounts=>{const el=app.querySelector('#accounts');if(!el||tab!=='accounts')return;el.innerHTML=accounts.map(a=>`<form class="account-editor" data-account-id="${esc(a.id)}"><div><strong>${esc(a.email)}</strong><small>${a.id===me.id?'Ditt konto':''}</small></div><label class="field">Roll<select name="role">${roleOptions(a.role)}</select></label><button type="submit">Spara roll</button><p role="status"></p></form>`).join('');el.querySelectorAll('form').forEach(form=>form.onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('admins/'+encodeURIComponent(form.dataset.accountId),'PATCH',{role:form.elements.role.value});me=await api('me');render();message('Kontots roll har sparats. Behörigheten gäller direkt.')}catch(err){form.querySelector('[role=status]').textContent=err.message;button.disabled=false}})}).catch(err=>message(err.message));
 app.querySelector('#account').onsubmit=async e=>{e.preventDefault();const button=e.submitter;button.disabled=true;try{await api('admins','POST',Object.fromEntries(new FormData(e.target)));render();message('Kontot har skapats med vald roll.')}catch(err){app.querySelector('#account-result').textContent=err.message;button.disabled=false}};
}

try{await load()}catch(err){login(err.message)}
